  @fallback "minus-small"

  @doc "Every icon name that resolves to real geometry."
  def names, do: Map.keys(@icons)

  @doc "True when `name` resolves to real geometry rather than the fallback."
  def known?(name), do: Map.has_key?(@icons, name)

  @doc """
  The hidden `<symbol>` definitions. Render once per page, just inside
  `<body>` — `<use>` elements elsewhere reference these by id.
  """
  def sprite(assigns) do
    assigns = assign(assigns, :icons, @icons)

    ~H"""
    <svg xmlns="http://www.w3.org/2000/svg" style="display:none" aria-hidden="true">
      <%= for {name, body} <- @icons do %>
        <symbol id={"i-" <> name} viewBox="0 0 24 24" fill="none"
                stroke="currentColor" stroke-width="1.5"
                stroke-linecap="round" stroke-linejoin="round">
          <%= Phoenix.HTML.raw(body) %>
        </symbol>
      <% end %>
    </svg>
    """
  end

  attr :name, :string, required: true
  attr :class, :string, default: nil
  attr :rest, :global

  @doc """
  One icon, as a `<use>` reference into the sprite.

  Inherits `currentColor`, so colour it with plain CSS `color` on any
  ancestor. Unknown names fall back rather than raising.
  """
  def icon(assigns) do
    assigns = assign(assigns, :resolved, if(known?(assigns.name), do: assigns.name, else: @fallback))

    ~H"""
    <svg class={["vp-icon", @class]} aria-hidden="true" focusable="false" {@rest}>
      <use href={"#i-" <> @resolved} />
    </svg>
    """
  end
end
